function example() {
  const [active, setActive] = React.useState(false);

  return (
    <Tags>
      <Tag as="a" href="#components" color="info">
        Components
      </Tag>
      <Tag
        as="button"
        color="primary"
        isLight={!active}
        aria-pressed={active}
        onClick={() => setActive(!active)}
      >
        Open issues
      </Tag>
    </Tags>
  );
}
